//! Lucide Library — FigCraft API 2 floating panel with the complete upstream icon catalogue.
use figcraft_plugin_sdk::{Input, Result, Value, call, entry, json, notify, set_setting, setting, show_ui};
include!(concat!(env!("OUT_DIR"), "/icons.rs"));
fn safe_color(v:&str)->&str{let s=v.trim();if s.len()==7&&s.starts_with('#')&&s[1..].bytes().all(|b|b.is_ascii_hexdigit()){s}else{"#111111"}}
fn filtered(q:&str)->Vec<&'static str>{let q=q.trim().to_ascii_lowercase();ICONS.iter().filter(|(n,_)|q.is_empty()||n.contains(&q)).map(|(n,_)|*n).collect()}
fn panel(v:&Value,q:&str)->Result<Value>{let names=filtered(q);let chosen=v["icon"].as_str().filter(|x|names.contains(x)).or_else(||names.first().copied()).unwrap_or("activity");show_ui(&json!({"title":"Lucide Library","controls":[{"type":"note","label":format!("{} Lucide icons · search by name",ICONS.len())},{"type":"text","name":"search","label":"Search icons","value":q},{"type":"list","name":"icon","label":"Icon","options":names,"value":chosen},{"type":"color","name":"stroke","label":"Stroke colour","value":safe_color(v["stroke"].as_str().unwrap_or("#111111"))},{"type":"slider","name":"width","label":"Stroke width","min":0.5,"max":4.0,"value":v["width"].as_f64().unwrap_or(2.0).clamp(0.5,4.0)},{"type":"button","name":"insert","label":"Insert editable icon"},{"type":"button","name":"close","label":"Close"}]}))?;Ok(Value::Null)}
fn insert(name:&str,color:&str,width:f64)->Result<Value>{let(_,d)=ICONS.iter().find(|(n,_)|*n==name).ok_or("Choose an icon")?;call("node.create",&json!({"type":"vector","path":d,"x":0,"y":0,"name":name,"props":{"fill":"none","stroke":safe_color(color),"strokeWeight":width.clamp(0.5,4.0),"strokeCap":"round","strokeJoin":"round"}}))?;notify(&format!("Inserted {name}"));Ok(json!({"inserted":name}))}
fn run(input:Input)->Result<Value>{if let Some(e)=input.event{let q=e.values["search"].as_str().unwrap_or_default().to_string();let icon=e.values["icon"].as_str().unwrap_or("activity").to_string();let color=e.values["stroke"].as_str().unwrap_or("#111111").to_string();let width=e.values["width"].as_f64().unwrap_or(2.0);match e.control.as_str(){"search"=>{set_setting("search",&json!(q))?;panel(&e.values,&q)?},"icon"|"stroke"|"width"=>panel(&e.values,&q)?,"insert"=>return insert(&icon,&color,width),"close"=>figcraft_plugin_sdk::close_ui(),_=>{}}return Ok(Value::Null)}let q=setting("search").and_then(|v|v.as_str().map(str::to_owned)).unwrap_or_default();panel(&Value::Null,&q)?;Ok(json!({"panel":"Lucide Library","icons":ICONS.len()}))}
entry!(run);
#[cfg(test)]mod tests{use super::*;#[test]fn full_catalogue_and_search(){assert!(ICONS.len()>1900);assert!(filtered("arrow").len()>50);assert!(filtered("accessibility").contains(&"accessibility"));assert!(filtered("no-such-icon").is_empty());}}
